parameters.jsCode:
const inp = $('Workflow Input').first().json;
const raw = $input.first().json;

const fallback = String(inp.fallback_text || '').trim();
let text = String((raw && (raw.output !== undefined ? raw.output : raw.text)) || '').trim();
let usedFallback = false;
let reason = '';

function fail(why) { usedFallback = true; reason = why; text = fallback; }

// The model is told not to wrap its output in quotes and sometimes does anyway.
if (text.length > 1 && text.charAt(0) === '"' && text.charAt(text.length - 1) === '"') {
  text = text.slice(1, -1).trim();
}

// facts_json is the only thing the model is allowed to quote. Accept either an
// array of strings or an object of them, so callers can pass whichever is
// natural for the turn.
let facts = [];
try {
  const parsed = JSON.parse(String(inp.facts_json || '[]'));
  if (Array.isArray(parsed)) {
    facts = parsed.map(function (f) { return String(f); });
  } else if (parsed && typeof parsed === 'object') {
    facts = Object.keys(parsed).map(function (k) { return String(parsed[k]); });
  }
} catch (e) { facts = []; }
facts = facts.filter(function (f) { return f && f.length > 0; });

if (!text) {
  fail('empty');
} else if (text.length > 1200) {
  fail('too_long');
} else {
  // Every quotable fact has to survive verbatim. A booking confirmation that
  // renames the time is worse than a stiff template that gets it right.
  for (let i = 0; i < facts.length; i++) {
    if (text.indexOf(facts[i]) === -1) { fail('missing_fact'); break; }
  }
}

if (!usedFallback) {
  // No digit run may reach the lead that did not come from somewhere real.
  // This is what blocks an invented price, date or meeting time.
  const allowed = [
    facts.join(' '),
    String(inp.choices_json || ''),
    String(inp.goal || ''),
    String(inp.lead_last_message || ''),
    String(inp.answer_text || ''),
    String(inp.known_json || ''),
    String(inp.history_json || '')
  ].join(' ');
  const runs = text.match(/[0-9]+/g) || [];
  for (let i = 0; i < runs.length; i++) {
    if (allowed.indexOf(runs[i]) === -1) { fail('unsourced_number'); break; }
  }
}

// Last resort: never return an empty message, whatever went wrong upstream.
if (!text) { text = fallback || 'Thanks - give me one moment.'; usedFallback = true; }

return [{ json: {
  ok: true,
  reply_text: text,
  text: text,
  used_fallback: usedFallback,
  fallback_reason: reason,
  slot_key: String(inp.slot_key || ''),
  asked_slot: inp.asked_slot === true,
  action: String(inp.action || '')
} }];
